INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a067f4-c458-7c57-a70b-d6b3ca1c1475'::uuid, '019f9df7-a2a2-790d-b90f-3e453f40cd4c'::uuid, 'A is the point (2, 4) and B is the point (m, n), where m and n are both positive integers less than 10. The gradient of the line AB is 2/3.

Find the coordinates of one of the possible positions for B.', '(5, 6) or (8, 8)', '(n - 4)/(m - 2) = 2/3.
One solution: n - 4 = 2 and m - 2 = 3, so B = (5, 6).
Another: n - 4 = 4 and m - 2 = 6, so B = (8, 8).', 'Medium', '{"tags":"sass-2022-p1,q14b","subtopic":"Gradient","question_type":"open","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-03T15:48:09.432Z'::timestamptz, '2026-09-03T15:48:09.432Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a067f4-c46a-74de-a142-698003260060'::uuid, '019f9df7-a2a2-78c7-aa4b-565799c65ce4'::uuid, 'Container A and container B are geometrically similar. The surface area of container A is 9/16 of the surface area of container B.

Container B has a diameter of 24 cm. Calculate the diameter of container A.', '18 cm', 'Area ratio A : B = 9 : 16, so linear ratio = sqrt(9/16) = 3/4.
d_A / 24 = 3/4
 d_A = 18 cm.', 'Medium', '{"tags":"sass-2022-p1,q15a","subtopic":"Similar solids","question_type":"open","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-03T15:48:09.450Z'::timestamptz, '2026-09-03T15:48:09.450Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a067f4-c47a-79e1-b19e-1880bc368241'::uuid, '019f9df7-a2a2-78c7-aa4b-565799c65ce4'::uuid, 'Container A and container B are geometrically similar. The surface area of container A is 9/16 of the surface area of container B.

Each container has chocolates in it. Container A costs $10.80. Calculate the cost of container B.', '$25.60', 'Linear ratio A : B = 3 : 4, so volume ratio = (3/4)^3 = 27/64.
Cost is proportional to volume, so Cost_B / 10.80 = 64/27.
Cost_B = 10.80 x 64/27 = $25.60.', 'Hard', '{"tags":"sass-2022-p1,q15b","subtopic":"Similar solids","question_type":"open","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-03T15:48:09.466Z'::timestamptz, '2026-09-03T15:48:09.466Z'::timestamptz) ON CONFLICT (id) DO NOTHING;